<?php
declare(strict_types=1);
require_once __DIR__.'/../config/bootstrap.php';require_once __DIR__.'/../config/governance.php';require_once __DIR__.'/../config/privacy.php';$admin=require_permission($pdo,'identity.review');$pageTitle='Geschützte Identitätsprüfung';$error='';$token='';$selectedId=is_string($_GET['id']??null)?(int)$_GET['id']:0;
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){require_csrf();try{$action=post_string('action');$selectedId=(int)post_string('request_id');if($action==='access')$token=verification_access_token($pdo,(int)$admin['id'],(int)post_string('document_id'),post_string('reason',1000));elseif($action==='decide'){verification_decide($pdo,(int)$admin['id'],$selectedId,post_string('decision'),post_string('reason',2000),($_POST['identity_confirmed']??'')==='1',($_POST['age_confirmed']??'')==='1');redirect('/admin/verifications.php?id='.$selectedId);}elseif($action==='privacy'){privacy_review_deletion($pdo,(int)$admin['id'],(int)post_string('deletion_id'),post_string('decision'),post_string('reason',4000),($_POST['retention_confirmed']??'')==='1');redirect('/admin/verifications.php');}else throw new InvalidArgumentException('Ungültige Aktion.');}catch(InvalidArgumentException|DomainException $e){http_response_code(422);$error=$e->getMessage();}}
$q=$pdo->prepare('SELECT r.*,u.username FROM market_verification_requests r JOIN users u ON u.id=r.user_id WHERE r.id=?');$q->execute([$selectedId]);$selected=$q->fetch();$documents=[];if($selected){$q=$pdo->prepare('SELECT id,deleted_at FROM market_verification_documents WHERE request_id=? ORDER BY id');$q->execute([$selectedId]);$documents=$q->fetchAll();}
$queue=$pdo->query("SELECT r.id,r.status,r.expires_at,u.username FROM market_verification_requests r JOIN users u ON u.id=r.user_id ORDER BY CASE r.status WHEN 'pending' THEN 0 WHEN 'needs_information' THEN 1 ELSE 2 END,r.id DESC LIMIT 100")->fetchAll();
include __DIR__.'/../includes/header.php';?>
<main class="container admin-page"><div class="page-heading"><p class="eyebrow">Need to know</p><h1>Dokumente kontrolliert prüfen.</h1><p>Jede Einsicht ist fallgebunden, begründet, kurz befristet und protokolliert. Keine Selbstfreigabe und keine Gleichsetzung von Identität, Alter und rechtlichen Erwerbsberechtigungen.</p></div><div class="admin-layout"><?php include __DIR__.'/../includes/admin-nav.php';?><div class="admin-content"><?php if($error):?><p class="notice error"><?=h($error)?></p><?php endif;?>
<?php if($token):?><section class="panel"><h2>Einmaliger Dokumentenzugriff</h2><form action="/marketplace/verification-document.php" method="post" target="_blank" rel="noopener noreferrer"><?=csrf_field()?><input type="hidden" name="token" value="<?=h($token)?>"><button class="button" type="submit">Dokument jetzt geschützt ansehen</button></form><p>Dieser Zugang gilt zwei Minuten, einmalig und nur für deine aktuelle Sitzung.</p></section><?php endif;?>
<?php if($selected):?><section class="panel"><h2>Antrag #<?=(int)$selected['id']?> · <?=h($selected['username'])?></h2><p>Status <?=h($selected['status'])?> · Frist <?=h($selected['expires_at'])?> UTC</p><?php foreach($documents as $document):?><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="access"><input type="hidden" name="request_id" value="<?=(int)$selected['id']?>"><input type="hidden" name="document_id" value="<?=(int)$document['id']?>"><label class="field">Einsichtsgrund für Dokument #<?=(int)$document['id']?><input name="reason" minlength="10" maxlength="1000" required></label><button class="button secondary" type="submit" <?=$document['deleted_at']?'disabled':''?>>Zugriff anfordern</button></form><?php endforeach;?>
<form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="decide"><input type="hidden" name="request_id" value="<?=(int)$selected['id']?>"><label class="field">Entscheidung<select name="decision"><option value="approved">Prüffeststellung bestätigen</option><option value="rejected">Ablehnen</option><option value="needs_information">Nachforderung</option></select></label><label><input type="checkbox" name="identity_confirmed" value="1"> Identität wurde nachvollziehbar bestätigt.</label><label><input type="checkbox" name="age_confirmed" value="1"> Mindestalter 18 Jahre wurde gesondert festgestellt.</label><label class="field">Begründung / Nachforderung<textarea name="reason" minlength="10" maxlength="2000" required></textarea></label><button class="button" type="submit">Prüfentscheidung speichern</button></form></section><?php endif;?>
<section class="panel"><h2>Prüfwarteschlange</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Antrag</th><th>Konto</th><th>Status</th><th>Frist</th></tr></thead><tbody><?php foreach($queue as $row):?><tr><td><a href="?id=<?=(int)$row['id']?>">#<?=(int)$row['id']?></a></td><td><?=h($row['username'])?></td><td><?=h($row['status'])?></td><td><?=h($row['expires_at'])?> UTC</td></tr><?php endforeach;?></tbody></table></div></section></div></div></main><?php include __DIR__.'/../includes/footer.php';?>
